// vkernels/kernels/dsa.hpp
//
// DeepseekSparseAttn (DSA) sparse-MLA forward — the GLM-5.3-Flash / DeepSeek-V3
// sparse-attention path (issue #51). An *indexer* (out of scope here) has
// already selected, per query token, the top-`topk` most relevant KV tiles
// (`indices`). This kernel scores each query against those selected keys and
// produces the combined attention output.
//
// The query/key are `dim + tail_dim` wide and the value is `d_v = dim - tail_dim`
// wide (the absorbed-MLA form: the nope key latent IS the value, width `d_v`,
// and the decoupled RoPE key contributes the extra `tail_dim`). Both shapes
// MUST work:
//
//   * GLM-5.3-Flash : qk_nope_head_dim = v_head_dim = 256, qk_rope_head_dim = 0
//                     -> dim = 256, tail_dim = 0, d_v = 256. There is NO rope
//                        tail, so the tail QK dot is skipped entirely. This is
//                        the shape tilelang cannot compile (a zero-size
//                        `Q_tail_buf`/`K_tail_shared` GEMM); the HIP kernel
//                        below guards `tail_dim == 0` and skips that dot.
//   * DeepSeek-V3   : qk_nope_head_dim = v_head_dim = 512, qk_rope_head_dim = 64
//                     -> dim = 576, tail_dim = 64, d_v = 512.
//
// Tensors (kv_group == 1; all heads share one key/value head):
//
//   q       : [1, S_q,  H,  dim + tail_dim]  bf16 (device) / fp32 (oracle)
//             q[i,h] = [ q_main (dim)  |  q_tail (tail_dim) ]   (tail may be 0)
//   kv      : [1, S_kv, kv_group, dim + tail_dim]  bf16 / fp32
//             kv[j,0] = [ v (d_v)  |  k_nope_extra (tail_dim)  |  k_rope (tail_dim) ]
//             so v[j]    = kv[j][0 : d_v]              (the value)
//                k_main[j]= kv[j][0 : dim]             (nope key, width dim)
//                k_tail[j]= kv[j][dim : dim + tail_dim] (rope key, width tail_dim)
//   indices : [1, S_q, kv_group, topk]   int32  (padded to a multiple of 64;
//             entries < 0 or >= S_kv are masked kpool tail tokens)
//   out     : [1, S_q, H, d_v]           bf16 / fp32   (combined)
//   lse     : [1, S_q, H]                fp32, nullable  (base-2 log-sum-exp)
//
// Computation (per query token i, head h; the selected keys are gathered via
// `indices[i,0,k]`):
//
//   raw[i,h,k]   = q_main[i,h] . k_main[idx] + (tail_dim>0) q_tail[i,h] . k_tail[idx]
//   score[i,h,k] = sm_scale * raw[i,h,k]            (sm_scale includes log2(e))
//   w[i,h,k]     = 2^(score[i,h,k] - lse[i,h])       (masked keys -> weight 0)
//   out[i,h]     = Σ_k w[i,h,k] * v[idx]              (d_v wide)
//   lse[i,h]     = log2( Σ_k 2^score[i,h,k] )          (base-2, when return_lse)
//
// `sm_scale = (1 / sqrt(dim + tail_dim)) * log2(e)`, so the weights are the
// standard natural-exp softmax `exp(raw/sqrt(dim+tail_dim)) / Σ` expressed in
// base-2 (FlashAttention's log2 trick). Masked keys contribute weight 0; if
// every selected key is masked the output row is 0 and the LSE is -inf.
//
// Two-implementation model (mirrors mla.{hpp,cpp,hip} from issue #21):
//   dsa.cpp  -- CPU reference (oracle), always compiled, in vkernels::kernels.
//               Two-pass numerically-stable base-2 softmax, fp32 throughout.
//   dsa.hip  -- HIP kernel (gfx942), compiled with VKERNELS_HAS_HIP. Online
//               softmax, fp32 accumulation, bf16 storage. Each block owns one
//               (query, head) pair and streams its `topk` selected keys,
//               accumulating the combined output directly (the per-group
//               partial_o / partial_lse from the tilelang kernel are an
//               internal parallelism detail; the combined result is
//               grouping-independent). Matches the oracle within tolerance.
#include <cstddef>
#include <cstdint>

namespace vkernels::kernels {

// CPU reference (oracle). Computes the sparse-MLA forward in fp32 with a
// numerically-stable two-pass base-2 softmax over the `topk` selected keys.
//
//   d_v = dim - tail_dim   (must be > 0; tail_dim may be 0)
//   topk % (block_I * inner_iter) must be 0 (the kernel's group tiling; the
//       oracle result is grouping-independent so this is validated, not used)
//   kv_group must be 1 (a single head_kv group is shared by all H heads)
//
// `lse` may be null when `return_lse` is false; otherwise it must be large
// enough for `S_q * H` fp32 values. `out` must not alias any input.
void dsa_sparse_fwd_cpu(int S_q, int S_kv, int H, int dim, int tail_dim,
                        int topk, int kv_group, int block_I, int inner_iter,
                        float sm_scale, bool return_lse,
                        const float* q, const float* kv,
                        const int32_t* indices, float* out, float* lse);

// Per-shape (decode vs prefill) launch tile selector. Writes the tile the
// HIP kernel should use:
//   decode  (S_q <= 8) : one query row per block, one wavefront (64 threads)
//   prefill (S_q >  8) : BQ query rows per block, 256 threads (4 wavefronts)
// `block_I` is the per-pass key tile (default 64); `inner_iter` repeats it so
// that `block_I * inner_iter` divides `topk` (default 1; raise it to trade
// register pressure for fewer passes on large topk).
void dsa_config_for(int S_q, int H, int dim, int topk, int* bq, int* threads,
                    int* block_I, int* inner_iter);

}  // namespace vkernels::kernels

#if VKERNELS_HAS_HIP
namespace vkernels::kernels::hip {

// HIP sparse-MLA forward (gfx942). Online softmax in fp32, bf16 storage,
// bf16-tolerant against the CPU oracle. `q`/`kv` are bf16 device pointers
// (`const __hip_bfloat16*`); `indices` is int32 device; `out` is bf16 device;
// `lse` is fp32 device (nullable when `return_lse` is false). Device pointers
// must reside in device or host-pinned memory. `tail_dim == 0` is handled by
// skipping the rope-tail dot at runtime (no zero-size GEMM).
void dsa_sparse_fwd(int S_q, int S_kv, int H, int dim, int tail_dim,
                    int topk, int kv_group, int block_I, int inner_iter,
                    float sm_scale, bool return_lse,
                    const void* q, const void* kv, const void* indices,
                    void* out, void* lse);

// Explicit-tile entry point (offline autotuner hook). Dispatches the concrete
// (bq, block_I, inner_iter) tile; threads is derived as max(bq,1)*64 capped
// at 256. `bn_kv` is reserved for a future tiled-key prefetch.
void dsa_sparse_fwd_with_tile(int S_q, int S_kv, int H, int dim, int tail_dim,
                              int topk, int kv_group, float sm_scale,
                              bool return_lse,
                              const void* q, const void* kv,
                              const void* indices, void* out, void* lse,
                              int bq, int block_I, int inner_iter, int bn_kv);

}  // namespace vkernels::kernels::hip
#endif  // VKERNELS_HAS_HIP
// vkernels/kernels/dsa.hip
//
// DeepseekSparseAttn (DSA) sparse-MLA forward (gfx942 / MI300A), issue #51.
// Online-softmax FlashAttention-style kernel over the `topk` INDEXER-SELECTED
// keys (see dsa.hpp): each block owns `BQ` query rows for one head and
// streams its selected keys one at a time, accumulating the combined output in
// fp32 with a numerically-stable base-2 online softmax.
//
//   score[i,h,k] = sm_scale . ( q_main[i,h] . k_main[idx]
//                              + (tail_dim>0) q_tail[i,h] . k_tail[idx] )
//   out[i,h]     = Sum_k softmax(score)[i,h,k] . v[idx]            (d_v wide)
//   lse[i,h]     = log2( Sum_k 2^score[i,h,k] )   (base-2, when return_lse)
//
// `sm_scale` already folds log2(e), so 2^score is the natural-exp weight and
// the base-2 LSE is the standard FlashAttention log-sum-exp.
//
// Storage. Following the established gfx942 bf16 convention (gemm_bf16.hip,
// moe_device.hip), bf16 is carried as raw uint16 IEEE-754 bit patterns and
// converted to/from fp32 with bf16_to_f32 (zero-extend of the top 16 bits)
// and f32bits_to_bf16 (round-to-nearest-even, the SAME helper the CPU oracle
// uses). The kernel is therefore bf16-tolerant against the oracle exactly as
// gemm_bf16 is.
//
// Tile & data layout. One wavefront (64 lanes) owns exactly one query row, so
// a block of `BQ` warps computes BQ rows. The head dimension (dim + tail_dim)
// is laid out STRIDED across the 64 lanes: lane `d` owns head elements
// {d, d+64, d+128, ...}. At the GLM-5.3 config (dim=256, tail_dim=0 -> W=256)
// that is 4 elements per lane and 4 output accumulators per lane; at the
// DeepSeek-V3 config (dim=576, tail_dim=64 -> W=640) it is 10 main + 1 tail +
// 8 output — well inside the register file, and exact (no bounds-checks fire).
// The per-key score is a single scalar, formed by a warp-shuffle reduction of
// the lane-local partial dot and therefore broadcast to every lane, which
// keeps the per-row online state (max, sum, output slice) lock-step across
// the warp with no LDS synchronisation on the hot path.
//
// tail_dim == 0 (GLM-5.3-Flash): the rope-tail dot loop runs zero iterations
// (the tile count `tail_tiles` is 0), so NO zero-size GEMM is ever issued —
// the exact case the tilelang code path cannot compile. The guard is a
// runtime branch on `tail_dim`, not a template specialization, so one binary
// serves both shapes.
//
// Memory. Each selected key's kv vector is read exactly once from global
// memory (bf16 -> fp32 on load); the BQ query rows are staged in LDS once per
// block (bf16 -> fp32). This is the simple, correct baseline (one key at a
// time, no double-buffered key tile); a tiled key prefetch is a follow-on
// optimisation, not required for correctness against the oracle. The combined
// result is grouping-independent, so each block streams all of its `topk`
// keys directly (no separate partial_o / partial_lse + combine kernel).
//
// Two-implementation model:
//   dsa.cpp  -- CPU reference (oracle), always compiled, two-pass softmax.
//   dsa.hip  -- this file, compiled with VKERNELS_HAS_HIP, online softmax.
//               Cross-checked against the oracle by test_dsa_correct.hip.
#include <cstdint>

#include "vkernels/kernels/dsa.hpp"

#if VKERNELS_HAS_HIP
#  include "vkernels/kernels/moe_device.hip"  // shared bf16<->f32 + fp4 helpers
#  include <hip/hip_runtime.h>

namespace vkernels::kernels::hip {

// Largest supported head width (dim + tail_dim) -> 1024/64 = 16 per lane.
static constexpr int kMaxW = 1024;
static constexpr int kPerLane = (kMaxW + 63) / 64;  // head elements per lane


template <int BQ>
__global__ void dsa_sparse_fwd_kernel(
    const uint16_t* __restrict__ q,
    const uint16_t* __restrict__ kv,
    const int32_t* __restrict__ indices,
    uint16_t* __restrict__ out, float* __restrict__ lse_out,
    int S_q, int S_kv, int H, int dim, int tail_dim, int topk, int kv_group,
    float sm_scale, bool return_lse) {
  const int q_tile = blockIdx.x;
  const int h = blockIdx.y;            // kv_group == 1: one shared head_kv
  const int tid = threadIdx.x;
  const int warp = tid >> 6;           // which query row within the tile
  const int lane = tid & 63;           // strided head index this lane owns
  const int gi = q_tile * BQ + warp;   // global query row
  if (gi >= S_q) return;

  const int W = dim + tail_dim;
  const int d_v = dim - tail_dim;
  const int main_tiles = (dim + 63) / 64;
  const int tail_tiles = (tail_dim + 63) / 64;  // 0 when tail_dim == 0
  const int v_tiles = (d_v + 63) / 64;

  // --- stage the BQ query rows in LDS once (bf16 -> fp32, per-block) ---
  extern __shared__ float sQ[];       // sQ[BQ][W]
  for (int idx = tid; idx < BQ * W; idx += BQ * 64) {
    const int r = idx / W, c = idx % W;
    const int gr = q_tile * BQ + r;
    sQ[idx] = (gr < S_q) ? bf16_to_f32(
                  q[((size_t)gr * H + h) * W + c])
                         : 0.0f;
  }
  __syncthreads();

  const float* qrow = &sQ[warp * W];  // this warp's query row (fp32)
  const int32_t* idx_i =
      indices + (size_t)gi * kv_group * topk;  // kv_group == 1 -> gi*topk

  // Lane-local slices of the output accumulator (strided by 64 over d_v).
  float o[kPerLane];
  for (int t = 0; t < kPerLane; ++t) o[t] = 0.0f;
  float row_max = -INFINITY;          // running max (same on every lane)
  float row_sum = 0.0f;               // running denominator (same on every lane)

  for (int k = 0; k < topk; ++k) {
    const int32_t idx = idx_i[k];
    const bool valid = (idx >= 0) && (idx < S_kv);

    // --- lane-local partial score (main + tail), then warp-reduce ---
    float partial = 0.0f;
    if (valid) {
      const uint16_t* kv_p = kv + (size_t)idx * W;  // kv_group==1
      for (int t = 0; t < main_tiles; ++t) {
        const int d = lane + t * 64;
        if (d < dim) partial += qrow[d] * bf16_to_f32(kv_p[d]);
      }
      for (int t = 0; t < tail_tiles; ++t) {  // 0 iters when tail_dim == 0
        const int d = lane + t * 64;
        if (d < tail_dim)
          partial += qrow[dim + d] * bf16_to_f32(kv_p[dim + d]);
      }
    }
    float score = partial;
    for (int off = 32; off > 0; off >>= 1)  // warp-wide sum -> broadcast
      score += __shfl_xor(score, off);
    // Masked keys must contribute ZERO weight, so clamp their score to -inf
    // exactly as the CPU oracle does (else exp2(0-max)=1).
    score = valid ? (score * sm_scale) : -INFINITY;

    // --- online softmax update (lock-step; identical on every lane) ---
    const float new_max = fmaxf(row_max, score);
    const float exp_old = (row_max == -INFINITY) ? 0.0f : exp2f(row_max - new_max);
    const float exp_s = (score == -INFINITY) ? 0.0f : exp2f(score - new_max);
    row_sum = row_sum * exp_old + exp_s;
    for (int t = 0; t < v_tiles; ++t) o[t] *= exp_old;
    if (valid) {
      const uint16_t* vp = kv + (size_t)idx * W;  // v = kv[idx][0:d_v]
      for (int t = 0; t < v_tiles; ++t) {
        const int d = lane + t * 64;
        if (d < d_v) o[t] += exp_s * bf16_to_f32(vp[d]);
      }
    }
    row_max = new_max;
  }

  // --- normalise and write the lane-local output slice (fp32 -> bf16) ---
  const float inv = (row_sum > 0.0f) ? 1.0f / row_sum : 0.0f;
  uint16_t* orow = out + (((size_t)gi * H + h) * d_v);
  for (int t = 0; t < v_tiles; ++t) {
    const int d = lane + t * 64;
    if (d < d_v) orow[d] = f2bf(o[t] * inv);
  }
  if (return_lse) {
    const float l = (row_sum > 0.0f) ? (row_max + log2f(row_sum)) : -INFINITY;
    if (lane == 0) lse_out[(size_t)gi * H + h] = l;
  }
}

// ---------------------------------------------------------------------------
//  Launchers
// ---------------------------------------------------------------------------
namespace {
template <int BQ>
void launch(const void* q, const void* kv, const void* indices, void* out,
            void* lse, int S_q, int S_kv, int H, int dim, int tail_dim,
            int topk, int kv_group, float sm_scale, bool return_lse) {
  const int W = dim + tail_dim;
  const int shmem = BQ * W * sizeof(float);
  dim3 block(BQ * 64);
  dim3 grid((S_q + BQ - 1) / BQ, H, 1);
  dsa_sparse_fwd_kernel<BQ><<<grid, block, shmem, 0>>>(
      reinterpret_cast<const uint16_t*>(q),
      reinterpret_cast<const uint16_t*>(kv),
      reinterpret_cast<const int32_t*>(indices),
      reinterpret_cast<uint16_t*>(out), reinterpret_cast<float*>(lse),
      S_q, S_kv, H, dim, tail_dim, topk, kv_group, sm_scale, return_lse);
}
}  // namespace

void dsa_sparse_fwd_with_tile(int S_q, int S_kv, int H, int dim, int tail_dim,
                              int topk, int kv_group, float sm_scale,
                              bool return_lse,
                              const void* q, const void* kv,
                              const void* indices, void* out, void* lse,
                              int bq, int block_I, int inner_iter, int bn_kv) {
  (void)block_I;     // baseline streams one key at a time; reserved for a
  (void)inner_iter;  // future tiled-key prefetch (group-then-combine merge).
  (void)bn_kv;
  if (bq <= 1)
    launch<1>(q, kv, indices, out, lse, S_q, S_kv, H, dim, tail_dim, topk,
              kv_group, sm_scale, return_lse);
  else if (bq <= 2)
    launch<2>(q, kv, indices, out, lse, S_q, S_kv, H, dim, tail_dim, topk,
              kv_group, sm_scale, return_lse);
  else if (bq <= 4)
    launch<4>(q, kv, indices, out, lse, S_q, S_kv, H, dim, tail_dim, topk,
              kv_group, sm_scale, return_lse);
  else
    launch<8>(q, kv, indices, out, lse, S_q, S_kv, H, dim, tail_dim, topk,
              kv_group, sm_scale, return_lse);
}

void dsa_sparse_fwd(int S_q, int S_kv, int H, int dim, int tail_dim,
                    int topk, int kv_group, int block_I, int inner_iter,
                    float sm_scale, bool return_lse,
                    const void* q, const void* kv, const void* indices,
                    void* out, void* lse) {
  int bq = 0, th = 0, bi = 0, ii = 0;
  ::vkernels::kernels::dsa_config_for(S_q, H, dim, topk, &bq, &th, &bi, &ii);
  (void)th;
  (void)block_I;
  (void)inner_iter;
  dsa_sparse_fwd_with_tile(S_q, S_kv, H, dim, tail_dim, topk, kv_group,
                           sm_scale, return_lse, q, kv, indices, out, lse,
                           bq, bi, ii, 0);
}

}  // namespace vkernels::kernels::hip

#endif  // VKERNELS_HAS_HIP
// vkernels/kernels/dsa.cpp -- CPU reference (oracle) implementation.
//
// DeepseekSparseAttn (DSA) sparse-MLA forward (issue #51). This is the
// CPU/torch reference the gfx942 HIP kernel is checked against; it is always
// compiled (no GPU toolkit) and is the correctness oracle for both the host
// unit tests and the on-device `test_dsa_correct.hip` harness.
//
// See dsa.hpp for the layout, the absorbed-value / decoupled-rope contract,
// and the base-2 softmax. The combined output is grouping-independent, so the
// oracle computes a single two-pass softmax over all `topk` selected keys per
// (query, head); the `block_I`/`inner_iter` group tiling is validated but not
// used to form the result.
#include "vkernels/kernels/dsa.hpp"

#include <cmath>
#include <limits>
#include <vector>

#include "vkernels/util/error.hpp"

namespace vkernels::kernels {

void dsa_sparse_fwd_cpu(int S_q, int S_kv, int H, int dim, int tail_dim,
                        int topk, int kv_group, int block_I, int inner_iter,
                        float sm_scale, bool return_lse,
                        const float* q, const float* kv,
                        const int32_t* indices, float* out, float* lse) {
  const int d_v = dim - tail_dim;
  VK_EXPECTS(dim > 0 && tail_dim >= 0 && d_v > 0, "dim > tail_dim >= 0 required");
  VK_EXPECTS(topk > 0, "topk must be positive");
  VK_EXPECTS(kv_group == 1, "kv_group must be 1 (single shared head_kv)");
  // block_I / inner_iter are the kernel's group-tiling CONFIGURATION hints
  // (the indexer pads `topk` to a multiple of block_I in the sglang layout).
  // The forward scores every selected key directly, so divisibility is a
  // caller convention, not a math requirement (mirrors MLA's bn_kv).
  VK_EXPECTS(block_I > 0 && inner_iter > 0, "block_I and inner_iter must be positive");
  VK_EXPECTS(S_q == 0 || H == 0 || q != nullptr, "q must not be null");
  VK_EXPECTS(S_q == 0 || H == 0 || S_kv == 0 || kv != nullptr,
             "kv must not be null");
  VK_EXPECTS(S_q == 0 || H == 0 || topk == 0 || indices != nullptr,
             "indices must not be null");
  VK_EXPECTS(S_q == 0 || H == 0 || out != nullptr, "out must not be null");
  VK_EXPECTS(!return_lse || lse != nullptr, "lse must not be null");
  if (S_q == 0 || H == 0 || topk == 0) return;  // nothing to do
  // S_kv == 0: every selected index is out of range -> all rows zero.
  const int W = dim + tail_dim;
  const float kNegInf = -std::numeric_limits<float>::infinity();
  std::vector<float> w(topk);

  for (int i = 0; i < S_q; ++i) {
    const int32_t* idx_i = indices + (size_t)i * kv_group * topk;  // kv_group==1
    for (int h = 0; h < H; ++h) {
      const float* qh = q + (((size_t)i * H + h) * W);
      const float* q_main = qh;
      const float* q_tail = qh + dim;
      float* oh = out + (((size_t)i * H + h) * d_v);
      float* lh = return_lse ? (lse + ((size_t)i * H + h)) : nullptr;

      // --- pass 1: scores + running max (numerically stable) ---
      float max_s = kNegInf;
      for (int k = 0; k < topk; ++k) {
        const int32_t idx = idx_i[k];
        if (idx < 0 || idx >= S_kv) { w[k] = kNegInf; continue; }
        const float* kv_p = kv + (size_t)idx * W;  // kv_group==1 -> j*W
        float dot = 0.0f;
        for (int d = 0; d < dim; ++d) dot += q_main[d] * kv_p[d];
        for (int d = 0; d < tail_dim; ++d)  // skipped when tail_dim == 0
          dot += q_tail[d] * kv_p[dim + d];
        const float s = sm_scale * dot;
        w[k] = s;
        if (s > max_s) max_s = s;
      }

      // --- pass 2: base-2 softmax denominator + weighted accumulation ---
      if (max_s == kNegInf) {  // every selected key masked (e.g. all -1)
        for (int d = 0; d < d_v; ++d) oh[d] = 0.0f;
        if (lh) *lh = kNegInf;
        continue;
      }
      float sum = 0.0f;
      for (int k = 0; k < topk; ++k) {
        if (w[k] == kNegInf) { w[k] = 0.0f; continue; }
        w[k] = std::exp2(w[k] - max_s);
        sum += w[k];
      }
      const float inv = 1.0f / sum;
      for (int d = 0; d < d_v; ++d) oh[d] = 0.0f;
      for (int k = 0; k < topk; ++k) {
        if (w[k] == 0.0f) continue;  // masked key
        const int32_t idx = idx_i[k];
        const float* vj = kv + (size_t)idx * W;  // v = kv[idx][0:d_v]
        const float a = w[k] * inv;
        for (int d = 0; d < d_v; ++d) oh[d] += a * vj[d];
      }
      if (lh) *lh = max_s + std::log2(sum);
    }
  }
}

void dsa_config_for(int S_q, int H, int dim, int topk, int* bq, int* threads,
                    int* block_I, int* inner_iter) {
  (void)H;
  (void)dim;
  // Decode: a single query streams its `topk` selected keys; one wavefront
  // keeps the per-row online state in registers and saturates the CUs.
  // Prefill: BQ query rows per block shares the key reads across rows.
  if (S_q <= 8) {
    *bq = 1;
    *threads = 64;  // one wavefront
  } else {
    *bq = 4;
    *threads = 256;  // four wavefronts
  }
  *block_I = 64;
  // inner_iter so that block_I * inner_iter divides topk (power-of-two topk
  // is the common case; fall back to 1).
  int ii = 1;
  while (ii < 8 && topk % (*block_I * (ii * 2)) == 0) ii *= 2;
  *inner_iter = ii;
}

}  // namespace vkernels::kernels
 * vLLM's TRITON_MLA / AITER *absorbed* semantics. `q` carries its own
 * RoPE slice; `k_c`/`v_c` are the compressed latent (kv_lora_rank);
 * `k_pe` is the decoupled RoPE part.
 *
 *   q           [B, S_q, H, kv_lora_rank + qk_rope_head_dim]  float32
 *   k_c         [B, S_kv, kv_lora_rank]                       float32
 *   k_pe        [B, S_kv, qk_rope_head_dim]                   float32
 *   v_c         [B, S_kv, kv_lora_rank]                       float32
 *   out         [B, S_q, H, kv_lora_rank]                     float32
 *   q_start/kv_start  row offsets into the (B, S) batch
 *   scale             1/sqrt(kv_lora_rank + qk_rope_head_dim)
 */
void vk_hip_mla_fwd(
    int B, int H, int S_q, int S_kv, int q_start, int kv_start,
    int kv_lora_rank, int qk_rope_head_dim, float scale,
    const float* q, const float* k_c, const float* k_pe,
    const float* v_c, float* out);

/* ------------------------------------------------------------------ */
/* DSA sparse-MLA forward (src/c/vkernels/kernels/dsa.hip, #51)      */
/* ------------------------------------------------------------------ */
/*
 * DeepseekSparseAttn (GLM-5.3-Flash / DeepSeek-V3) sparse-MLA forward.
 * The indexer has already selected, per query token, the top-`topk` KV
 * tiles (`indices`); this kernel scores each query against those keys and
 * produces the combined attention output.
 *
 *   q       [1, S_q,  H,  dim + tail_dim]      bf16
 *   kv      [1, S_kv, kv_group, dim + tail_dim] bf16  (kv_group == 1)
 *   indices [1, S_q, kv_group, topk]           int32 (<0/>=S_kv masked)
 *   out     [1, S_q, H, dim - tail_dim]        bf16
 *   lse     [1, S_q, H]                         fp32 (nullable; set when
 *                                                    return_lse != 0)
 *   sm_scale = (1/sqrt(dim + tail_dim)) * log2(e)   (folds log2(e))
 *
 * tail_dim == 0 (GLM-5.3) is handled by skipping the rope-tail dot at
 * runtime -- no zero-size GEMM, the exact case the tilelang code path
 * cannot compile. Online base-2 softmax, fp32 accumulation.
 */
void vk_hip_dsa_sparse_fwd(
    int S_q, int S_kv, int H, int dim, int tail_dim, int topk, int kv_group,
    int block_I, int inner_iter, float sm_scale, int return_lse,
    const void* q, const void* kv, const void* indices, void* out, void* lse);

/* Per-shape (bq, threads, block_I, inner_iter) tile selector for the HIP
 * DSA kernel (mirrors vk_dsa_config). Never throws. */
void vk_hip_dsa_config(int S_q, int H, int dim, int topk, int* bq,
                       int* threads, int* block_I, int* inner_iter);

/* ------------------------------------------------------------------ */
/* MHC multi-head hybrid-attention pre-norm (src/c/vkernels/kernels/    */
/* mhc.hip, #51 part 2)                                                 */
/* ------------------------------------------------------------------ */
/*
 * Two gfx942 HIP kernels re-implementing the tilelang MHC kernels that
 * fault/abort on MI300A (dynamic-shared > 64 KB non-optin cap). This is
 * the "vkernels HIP MHC path" that runs WITHOUT the hidden_block 256->128
 * workaround: static shared memory, no pipelining, no hipFuncSetAttribute
 * opt-in.
 *
 *   mhc_pre_gemm_sqrsum:
 *     x      [num_tokens, hc_hidden_size]  bf16   (hc_hidden=hc_mult*hidden)
 *     fn     [hc_mult3,    hc_hidden_size] fp32   (hc_mult3=hc_mult*(2+hc_mult))
 *     out    [num_tokens, hc_mult3]        fp32   (= x @ fn^T)
 *     sqrsum [num_tokens]                  fp32   (= sum_h x[n,h]^2)
 *     hc_mult3 <= 32; hc_hidden_size <= 28672.
 *
 *   mhc_post:
 *     a (comb_res_mix)[num_tokens, hc, hc]    fp32
 *     b (residual)   [num_tokens, hc, hidden] bf16
 *     c (post_layer_mix)[num_tokens, hc]      fp32
 *     d (x)          [num_tokens, hidden]     bf16
 *     out[n,j,h] = c[n,j]*d[n,h] + sum_k a[n,k,j]*b[n,k,h]   (bf16)
 *     hc <= 63.
 */
void vk_hip_mhc_pre_gemm_sqrsum(int num_tokens, int hc_mult3, int hc_hidden_size,
  if (Nl > 1024)  // single-block shared memory; caller falls back to CPU
    return VK_ERROR_UNSUPPORTED;
  vkernels::kernels::hip::moe_align_block_size_hip(
      topk_ids, expert_map, M, top_k, block_size, num_experts, local_n,
      max_EM, sorted_ids, expert_ids, out_EM, stream);
  return VK_OK;
}
extern "C" void vk_hip_mla_fwd(
    int B, int H, int S_q, int S_kv, int q_start, int kv_start,
    int kv_lora_rank, int qk_rope_head_dim, float scale,
    const float* q, const float* k_c, const float* k_pe,
