  EXPECT_NEAR(out[0], 1.0f, 1e-6);
  EXPECT_NEAR(out[1], 0.0f, 1e-6);
  EXPECT_NEAR(lse[0], 1.0f, 1e-6);  // mx=1 + log2(1)=0

  // Out-of-range index (>= S_kv) is masked too.
  std::vector<int32_t> idx2 = {0, 5};
