#include "vkernels/kernels/dsa_topk.hpp"

using vkernels::kernels::dsa_topk_transform_cpu;
using vkernels::kernels::dsa_topk_transform_group_topk_supported;

TEST(DsaTopKTransform, ShortRowsBypassRadixAndAppendTail) {
  constexpr int32_t batch = 1;
  constexpr int32_t stride = 128;
  constexpr int32_t pool = 4;
  constexpr int32_t token_topk = 128 * pool;
  constexpr int32_t out_cols = token_topk + pool - 1;
  std::vector<float> score(stride, 0.0f);
  std::vector<int32_t> lengths = {3};
  std::vector<int32_t> seq_lens = {14};  // 3 full pools + 2 tail tokens
  std::vector<int32_t> out(out_cols, 99);

  dsa_topk_transform_cpu(batch, score.data(), lengths.data(), out.data(),
                         stride, pool, token_topk, out_cols, nullptr, 0,
                         nullptr, nullptr, nullptr, seq_lens.data());

  for (int32_t i = 0; i < 14; ++i) EXPECT_EQ(out[i], i);
  for (int32_t i = 14; i < out_cols; ++i) EXPECT_EQ(out[i], -1);
}

TEST(DsaTopKTransform, SelectsHighestScoringGroups) {
  constexpr int32_t length = 130;
  constexpr int32_t pool = 2;
  constexpr int32_t group_topk = 128;
  constexpr int32_t token_topk = group_topk * pool;
  std::vector<float> score(length);
  std::iota(score.begin(), score.end(), 0.0f);
  std::vector<int32_t> lengths = {length};
  std::vector<int32_t> out(token_topk, -1);

  dsa_topk_transform_cpu(1, score.data(), lengths.data(), out.data(), length,
                         pool, token_topk, token_topk, nullptr, 0, nullptr,
                         nullptr, nullptr, nullptr);
  std::sort(out.begin(), out.end());
  for (int32_t i = 0; i < token_topk; ++i)
    EXPECT_EQ(out[i], i + 2 * pool);
}

TEST(DsaTopKTransform, AppliesRowStartAndRaggedOffset) {
  constexpr int32_t row_start = 3;
  constexpr int32_t length = 129;
  constexpr int32_t stride = row_start + length;
  constexpr int32_t pool = 2;
  constexpr int32_t token_topk = 128 * pool;
  std::vector<float> score(stride, -1000.0f);
  for (int32_t i = 0; i < length; ++i) score[row_start + i] = i;
  std::vector<int32_t> lengths = {length};
  std::vector<int32_t> row_starts = {row_start};
  std::vector<int32_t> offsets = {1000};
  std::vector<int32_t> out(token_topk, -1);

