}

TEST(DsaTopKTransform, UsesExplicitPageTableRows) {
  constexpr int32_t batch = 2;
  constexpr int32_t stride = 128;
  constexpr int32_t page_stride = 300;
  constexpr int32_t pool = 2;
  constexpr int32_t token_topk = 128 * pool;
