  std::vector<int32_t> lengths = {2, 2};
  std::vector<int32_t> page_table(batch * page_stride);
  for (int32_t i = 0; i < page_stride; ++i) {
    page_table[i] = 1000 + i;
    page_table[page_stride + i] = 2000 + i;
