   41	    int32_t token_topk, int32_t out_cols, const int32_t* page_table,
   42	    int64_t page_table_stride, const int32_t* page_table_row_index,
   43	    const int32_t* topk_indices_offset, const int32_t* row_starts,
   44	    const int32_t* seq_lens) {
