   46	  VK_EXPECTS(score_stride >= 0, "score_stride must be non-negative");
   47	  VK_EXPECTS(pool_size > 1, "pool_size must be greater than one");
   48	  VK_EXPECTS(token_topk > 0 && token_topk % pool_size == 0,
   49	             "token_topk must be a positive multiple of pool_size");
   50	  const int32_t group_topk = token_topk / pool_size;
   51	  VK_EXPECTS(dsa_topk_transform_group_topk_supported(group_topk),
   52	             "unsupported pool-level top-k");
   53	  const int32_t tail_cols = seq_lens == nullptr ? 0 : pool_size - 1;
   54	  VK_EXPECTS(out_cols == token_topk + tail_cols,
   55	             "out_cols does not match the transform layout");
   56	  VK_EXPECTS(page_table == nullptr || topk_indices_offset == nullptr,
   57	             "page_table and topk_indices_offset are mutually exclusive");
   58	  VK_EXPECTS(page_table == nullptr || page_table_stride > 0,
   59	             "page_table_stride must be positive when a page table is used");
   60	  VK_EXPECTS(batch_size == 0 || score != nullptr, "score must not be null");
   61	  VK_EXPECTS(batch_size == 0 || lengths != nullptr, "lengths must not be null");
   62	  VK_EXPECTS(batch_size == 0 || dst_token_indices != nullptr,
   63	             "dst_token_indices must not be null");
   64	  if (batch_size == 0) return;
   65	
   66	  std::vector<int32_t> selected;
   67	  for (int32_t row = 0; row < batch_size; ++row) {
   68	    const int32_t length = lengths[row];
   69	    const int32_t row_start = row_starts == nullptr ? 0 : row_starts[row];
   70	    VK_EXPECTS(length >= 0, "lengths entries must be non-negative");
   71	    VK_EXPECTS(row_start >= 0, "row_starts entries must be non-negative");
   72	    VK_EXPECTS(static_cast<int64_t>(row_start) + length <= score_stride,
