   39	template <int K>
   40	__device__ void radix_topk(const float* __restrict__ input,
   41	                           int32_t* __restrict__ indices, int32_t row_start,
   42	                           int32_t length) {
   43	  int32_t topk = K;
   44	
   45	  __shared__ __align__(128) int32_t histogram_buf[2][kRadix + 128];
   46	  __shared__ __align__(128) int32_t counter;
   47	  __shared__ __align__(128) int32_t threshold_bin_id;
   48	  __shared__ __align__(128) int32_t num_input[2];
   49	  int32_t* histogram = histogram_buf[0];
   50	  extern __shared__ int32_t staged_indices[];
   51	
   52	  const int32_t tid = static_cast<int32_t>(threadIdx.x);
   53	  if (tid < kRadix + 1) histogram[tid] = 0;
   54	  __syncthreads();
   55	
   56	  for (int32_t idx = tid; idx < length; idx += kThreadsPerBlock)
   57	    atomicAdd(&histogram[coarse_float_key(input[row_start + idx])], 1);
   58	  __syncthreads();
   59	
   60	  const auto run_reverse_cumsum = [&]() {
   61	#pragma unroll 8
   62	    for (int32_t i = 0; i < 8; ++i) {
   63	      if (tid < kRadix) {
   64	        const int32_t delta = 1 << i;
   65	        const int32_t buffer = i & 1;
   66	        int32_t value = histogram_buf[buffer][tid];
   67	        if (tid < kRadix - delta)
   68	          value += histogram_buf[buffer][tid + delta];
   69	        histogram_buf[buffer ^ 1][tid] = value;
   70	      }
   71	      __syncthreads();
   72	    }
   73	  };
   74	
   75	  run_reverse_cumsum();
   76	  if (tid < kRadix && histogram[tid] > topk &&
   77	      histogram[tid + 1] <= topk) {
   78	    threshold_bin_id = tid;
   79	    num_input[0] = 0;
   80	    counter = 0;
   81	  }
   82	  __syncthreads();
   83	
   84	  int32_t threshold_bin = threshold_bin_id;
   85	  topk -= histogram[threshold_bin + 1];
   86	  if (topk == 0) {
   87	    for (int32_t idx = tid; idx < length; idx += kThreadsPerBlock) {
   88	      if (static_cast<int32_t>(coarse_float_key(input[row_start + idx])) >
   89	          threshold_bin) {
   90	        const int32_t pos = atomicAdd(&counter, 1);
   91	        indices[pos] = idx;
   92	      }
   93	    }
   94	    __syncthreads();
   95	    return;
   96	  }
   97	
   98	  if (tid < kRadix + 1) histogram[tid] = 0;
   99	  __syncthreads();
  100	  for (int32_t idx = tid; idx < length; idx += kThreadsPerBlock) {
  101	    const float value = input[row_start + idx];
  102	    const int32_t bin = static_cast<int32_t>(coarse_float_key(value));
  103	    if (bin > threshold_bin) {
  104	      const int32_t pos = atomicAdd(&counter, 1);
  105	      indices[pos] = idx;
  106	    } else if (bin == threshold_bin) {
  107	      const int32_t pos = atomicAdd(&num_input[0], 1);
  108	      if (pos < kSmemInputSize) {
  109	        staged_indices[pos] = idx;
  110	        atomicAdd(&histogram[(ordered_float_key(value) >> 24) & 0xffu], 1);
  111	      }
  112	    }
  113	  }
  114	  __syncthreads();
  115	
  116	#pragma unroll 4
  117	  for (int32_t round = 0; round < 4; ++round) {
  118	    __shared__ int32_t last_remain;
  119	    const int32_t current = round & 1;
  120	    const int32_t raw_count = num_input[current];
  121	    const int32_t count =
  122	        raw_count < kSmemInputSize ? raw_count : kSmemInputSize;
  123	
  124	    run_reverse_cumsum();
  125	    if (tid < kRadix && histogram[tid] > topk &&
  126	        histogram[tid + 1] <= topk) {
  127	      threshold_bin_id = tid;
  128	      num_input[current ^ 1] = 0;
  129	      last_remain = topk - histogram[tid + 1];
  130	    }
  131	    __syncthreads();
  132	
  133	    threshold_bin = threshold_bin_id;
  134	    topk -= histogram[threshold_bin + 1];
  135	    const int32_t key_shift = 24 - round * 8;
  136	    if (topk == 0) {
  137	      for (int32_t i = tid; i < count; i += kThreadsPerBlock) {
  138	        const int32_t idx = staged_indices[current * kSmemInputSize + i];
  139	        const int32_t bin =
  140	            static_cast<int32_t>((ordered_float_key(input[row_start + idx]) >>
  141	                                  key_shift) &
  142	                                 0xffu);
  143	        if (bin > threshold_bin) {
  144	          const int32_t pos = atomicAdd(&counter, 1);
  145	          indices[pos] = idx;
  146	        }
  147	      }
  148	      __syncthreads();
  149	      break;
  150	    }
  151	
  152	    if (tid < kRadix + 1) histogram[tid] = 0;
  153	    __syncthreads();
  154	    for (int32_t i = tid; i < count; i += kThreadsPerBlock) {
  155	      const int32_t idx = staged_indices[current * kSmemInputSize + i];
  156	      const float value = input[row_start + idx];
  157	      const int32_t bin = static_cast<int32_t>(
  158	          (ordered_float_key(value) >> key_shift) & 0xffu);
  159	      if (bin > threshold_bin) {
  160	        const int32_t pos = atomicAdd(&counter, 1);
  161	        indices[pos] = idx;
  162	      } else if (bin == threshold_bin) {
  163	        if (round == 3) {
  164	          const int32_t pos = atomicAdd(&last_remain, -1);
  165	          if (pos > 0) indices[K - pos] = idx;
  166	        } else {
  167	          const int32_t pos = atomicAdd(&num_input[current ^ 1], 1);
  168	          if (pos < kSmemInputSize) {
  169	            staged_indices[(current ^ 1) * kSmemInputSize + pos] = idx;
  170	            const int32_t sub_bin = static_cast<int32_t>(
  171	                (ordered_float_key(value) >> (key_shift - 8)) & 0xffu);
  172	            atomicAdd(&histogram[sub_bin], 1);
  173	          }
  174	        }
  175	      }
  176	    }
  177	    __syncthreads();
  178	  }
  179	}
