   15	int32_t transform_token(int32_t raw_token, const int32_t* page_table_row,
   16	                        const int32_t* topk_indices_offset, int32_t offset) {
   17	  if (page_table_row != nullptr) return page_table_row[raw_token];
   18	  if (topk_indices_offset != nullptr) return raw_token + offset;
