   38	void dsa_topk_transform_cpu(
   39	    int32_t batch_size, const float* score, const int32_t* lengths,
   40	    int32_t* dst_token_indices, int64_t score_stride, int32_t pool_size,
   41	    int32_t token_topk, int32_t out_cols, const int32_t* page_table,
   42	    int64_t page_table_stride, const int32_t* page_table_row_index,
   43	    const int32_t* topk_indices_offset, const int32_t* row_starts,
   44	    const int32_t* seq_lens) {
   45	  VK_EXPECTS(batch_size >= 0, "batch_size must be non-negative");
   46	  VK_EXPECTS(score_stride >= 0, "score_stride must be non-negative");
   47	  VK_EXPECTS(pool_size > 1, "pool_size must be greater than one");
   48	  VK_EXPECTS(token_topk > 0 && token_topk % pool_size == 0,
   49	             "token_topk must be a positive multiple of pool_size");
   50	  const int32_t group_topk = token_topk / pool_size;
   51	  VK_EXPECTS(dsa_topk_transform_group_topk_supported(group_topk),
   52	             "unsupported pool-level top-k");
   53	  const int32_t tail_cols = seq_lens == nullptr ? 0 : pool_size - 1;
   54	  VK_EXPECTS(out_cols == token_topk + tail_cols,
   55	             "out_cols does not match the transform layout");
   56	  VK_EXPECTS(page_table == nullptr || topk_indices_offset == nullptr,
   57	             "page_table and topk_indices_offset are mutually exclusive");
   58	  VK_EXPECTS(page_table == nullptr || page_table_stride > 0,
   59	             "page_table_stride must be positive when a page table is used");
   60	  VK_EXPECTS(batch_size == 0 || score != nullptr, "score must not be null");
   61	  VK_EXPECTS(batch_size == 0 || lengths != nullptr, "lengths must not be null");
   62	  VK_EXPECTS(batch_size == 0 || dst_token_indices != nullptr,
   63	             "dst_token_indices must not be null");
   64	  if (batch_size == 0) return;
   65	
   66	  std::vector<int32_t> selected;
   67	  for (int32_t row = 0; row < batch_size; ++row) {
   68	    const int32_t length = lengths[row];
   69	    const int32_t row_start = row_starts == nullptr ? 0 : row_starts[row];
   70	    VK_EXPECTS(length >= 0, "lengths entries must be non-negative");
   71	    VK_EXPECTS(row_start >= 0, "row_starts entries must be non-negative");
   72	    VK_EXPECTS(static_cast<int64_t>(row_start) + length <= score_stride,
   73	               "valid score range exceeds score_stride");
   74	    VK_EXPECTS(length <= std::numeric_limits<int32_t>::max() / pool_size,
   75	               "expanded token index overflows int32");
   76	
   77	    int32_t* dst = dst_token_indices + static_cast<size_t>(row) * out_cols;
   78	    std::fill(dst, dst + out_cols, -1);
   79	    const int32_t valid_groups = std::min(length, group_topk);
   80	    if (valid_groups > 0) {
   81	      selected.resize(length);
   82	      std::iota(selected.begin(), selected.end(), 0);
   83	      if (length > group_topk) {
   84	        const float* score_row = score + static_cast<size_t>(row) * score_stride +
   85	                                 row_start;
   86	        std::nth_element(
   87	            selected.begin(), selected.begin() + group_topk, selected.end(),
   88	            [score_row](int32_t a, int32_t b) {
   89	              if (score_row[a] == score_row[b]) return a < b;
   90	              return score_row[a] > score_row[b];
   91	            });
   92	        selected.resize(group_topk);
   93	      }
   94	    }
   95	
   96	    const int32_t page_row =
   97	        page_table_row_index == nullptr ? row : page_table_row_index[row];
   98	    VK_EXPECTS(page_table == nullptr || page_row >= 0,
   99	               "page_table_row_index entries must be non-negative");
  100	    const int32_t* page_table_entry =
  101	        page_table == nullptr ? nullptr
  102	                              : page_table + static_cast<size_t>(page_row) *
  103	                                                 page_table_stride;
  104	    const int32_t offset =
  105	        topk_indices_offset == nullptr ? 0 : topk_indices_offset[row];
  106	
  107	    const int32_t history_len = valid_groups * pool_size;
  108	    for (int32_t col = 0; col < history_len; ++col) {
  109	      const int32_t group_rank = col / pool_size;
  110	      const int32_t slot = col % pool_size;
  111	      const int32_t raw_token = selected[group_rank] * pool_size + slot;
  112	      VK_EXPECTS(page_table_entry == nullptr || raw_token < page_table_stride,
  113	                 "raw token exceeds page_table_stride");
  114	      dst[col] = transform_token(raw_token, page_table_entry,
  115	                                 topk_indices_offset, offset);
  116	    }
  117	
  118	    if (seq_lens != nullptr) {
  119	      VK_EXPECTS(seq_lens[row] >= 0, "seq_lens entries must be non-negative");
  120	      const int32_t tail_count = seq_lens[row] % pool_size;
  121	      for (int32_t tail = 0; tail < tail_count; ++tail) {
  122	        const int32_t raw_token = length * pool_size + tail;
  123	        VK_EXPECTS(page_table_entry == nullptr || raw_token < page_table_stride,
  124	                   "tail token exceeds page_table_stride");
  125	        dst[history_len + tail] = transform_token(
  126	            raw_token, page_table_entry, topk_indices_offset, offset);
  127	      }
  128	    }
  129	  }
