    1	// vkernels/kernels/dsa_topk.hip
    2	//
    3	// Radix top-k transform for the DSA kpool indexer (gfx942 / MI300A). The
    4	// radix selector is a HIP port of sglang's kpool_topk_transform JIT kernel:
    5	// an 8-bit fp16 coarse pass followed by fp32-key refinement. One workgroup
    6	// owns one score row, selects pool groups in shared memory, expands them to
    7	// token indices, then applies the optional page-table or ragged mapping.
    8	#include "vkernels/kernels/dsa_topk.hpp"
