  181	__device__ __forceinline__ int32_t transform_token(
  182	    int32_t raw_token, const int32_t* __restrict__ page_table_entry,
  183	    int64_t page_table_stride,
  184	    const int32_t* __restrict__ topk_indices_offset, int32_t offset) {
  185	  if (page_table_entry != nullptr) {
  186	    if (raw_token < 0 || raw_token >= page_table_stride) return -1;
  187	    return page_table_entry[raw_token];
  188	  }
  189	  if (topk_indices_offset != nullptr) return raw_token + offset;
  190	  return raw_token;
  191	}
  192	
  193	template <int K>
  194	__global__ __launch_bounds__(kThreadsPerBlock) void dsa_topk_transform_kernel(
  195	    const float* __restrict__ score, const int32_t* __restrict__ lengths,
  196	    int32_t* __restrict__ dst_token_indices, int64_t score_stride,
  197	    int32_t pool_size, int32_t token_topk, int32_t out_cols,
  198	    const int32_t* __restrict__ page_table, int64_t page_table_stride,
  199	    const int32_t* __restrict__ page_table_row_index,
  200	    const int32_t* __restrict__ topk_indices_offset,
  201	    const int32_t* __restrict__ row_starts,
  202	    const int32_t* __restrict__ seq_lens) {
  203	  const int32_t row = static_cast<int32_t>(blockIdx.x);
  204	  const int32_t tid = static_cast<int32_t>(threadIdx.x);
  205	  const int32_t length = lengths[row];
  206	  const int32_t row_start = row_starts == nullptr ? 0 : row_starts[row];
  207	  int32_t* dst = dst_token_indices + static_cast<size_t>(row) * out_cols;
  208	  const int32_t page_row =
  209	      page_table_row_index == nullptr ? row : page_table_row_index[row];
  210	  const bool invalid =
  211	      length < 0 || row_start < 0 ||
  212	      static_cast<int64_t>(row_start) + length > score_stride ||
  213	      (page_table != nullptr && page_row < 0) ||
  214	      (seq_lens != nullptr && seq_lens[row] < 0);
  215	  if (invalid) {
  216	    for (int32_t col = tid; col < out_cols; col += kThreadsPerBlock)
  217	      dst[col] = -1;
  218	    return;
  219	  }
  220	
  221	  const float* score_row = score + static_cast<size_t>(row) * score_stride;
  222	  const int32_t* page_table_entry =
  223	      page_table == nullptr
  224	          ? nullptr
  225	          : page_table + static_cast<size_t>(page_row) * page_table_stride;
  226	  const int32_t offset =
  227	      topk_indices_offset == nullptr ? 0 : topk_indices_offset[row];
  228	  const int32_t valid_groups = length < K ? length : K;
  229	  const int32_t history_len = valid_groups * pool_size;
  230	  const int32_t tail_count =
  231	      seq_lens == nullptr ? 0 : seq_lens[row] % pool_size;
  232	
  233	  if (length <= K) {
  234	    for (int32_t col = tid; col < out_cols; col += kThreadsPerBlock) {
  235	      if (col < history_len) {
  236	        dst[col] = transform_token(col, page_table_entry, page_table_stride,
  237	                                   topk_indices_offset, offset);
  238	      } else if (col < history_len + tail_count) {
  239	        const int32_t raw_token = length * pool_size + col - history_len;
  240	        dst[col] = transform_token(raw_token, page_table_entry,
  241	                                   page_table_stride, topk_indices_offset,
  242	                                   offset);
  243	      } else {
  244	        dst[col] = -1;
  245	      }
  246	    }
  247	    return;
  248	  }
  249	
  250	  __shared__ int32_t selected_groups[K];
  251	  radix_topk<K>(score_row, selected_groups, row_start, length);
  252	  for (int32_t col = tid; col < out_cols; col += kThreadsPerBlock) {
  253	    if (col < history_len) {
  254	      const int32_t group_id = selected_groups[col / pool_size];
  255	      const int32_t raw_token = group_id * pool_size + col % pool_size;
  256	      dst[col] = transform_token(raw_token, page_table_entry,
  257	                                 page_table_stride, topk_indices_offset,
  258	                                 offset);
  259	    } else if (col < history_len + tail_count) {
  260	      const int32_t raw_token = length * pool_size + col - history_len;
  261	      dst[col] = transform_token(raw_token, page_table_entry,
  262	                                 page_table_stride, topk_indices_offset,
  263	                                 offset);
  264	    } else {
  265	      dst[col] = -1;
  266	    }
  267	  }
  268	}
  269	
  270	template <int K>
  271	void launch(const float* score, const int32_t* lengths,
  272	            int32_t* dst_token_indices, int32_t batch_size,
  273	            int64_t score_stride, int32_t pool_size, int32_t token_topk,
  274	            int32_t out_cols, const int32_t* page_table,
  275	            int64_t page_table_stride, const int32_t* page_table_row_index,
  276	            const int32_t* topk_indices_offset, const int32_t* row_starts,
  277	            const int32_t* seq_lens) {
  278	  dsa_topk_transform_kernel<K><<<batch_size, kThreadsPerBlock,
  279	                                 kDynamicSmemBytes, 0>>>(
  280	      score, lengths, dst_token_indices, score_stride, pool_size, token_topk,
  281	      out_cols, page_table, page_table_stride, page_table_row_index,
  282	      topk_indices_offset, row_starts, seq_lens);
  283	}
  284	
  285	}  // namespace
  286	
  287	void dsa_topk_transform(
  288	    int32_t batch_size, const float* score, const int32_t* lengths,
  289	    int32_t* dst_token_indices, int64_t score_stride, int32_t pool_size,
  290	    int32_t token_topk, int32_t out_cols, const int32_t* page_table,
  291	    int64_t page_table_stride, const int32_t* page_table_row_index,
  292	    const int32_t* topk_indices_offset, const int32_t* row_starts,
  293	    const int32_t* seq_lens) {
  294	  if (batch_size <= 0 || score == nullptr || lengths == nullptr ||
  295	      dst_token_indices == nullptr || score_stride < 0 || pool_size <= 1 ||
  296	      token_topk <= 0 || token_topk % pool_size != 0 ||
  297	      out_cols != token_topk + (seq_lens == nullptr ? 0 : pool_size - 1) ||
  298	      (page_table != nullptr && topk_indices_offset != nullptr) ||
  299	      (page_table != nullptr && page_table_stride <= 0))
  300	    return;
  301	
  302	  const int32_t group_topk = token_topk / pool_size;
  303	#define VK_DSA_TOPK_LAUNCH(K)                                                \
  304	  launch<K>(score, lengths, dst_token_indices, batch_size, score_stride,     \
  305	            pool_size, token_topk, out_cols, page_table, page_table_stride,  \
  306	            page_table_row_index, topk_indices_offset, row_starts, seq_lens)
  307	  switch (group_topk) {
  308	    case 128: VK_DSA_TOPK_LAUNCH(128); break;
  309	    case 160: VK_DSA_TOPK_LAUNCH(160); break;
  310	    case 192: VK_DSA_TOPK_LAUNCH(192); break;
  311	    case 224: VK_DSA_TOPK_LAUNCH(224); break;
  312	    case 256: VK_DSA_TOPK_LAUNCH(256); break;
  313	    case 512: VK_DSA_TOPK_LAUNCH(512); break;
  314	    default: break;
  315	  }
  316	#undef VK_DSA_TOPK_LAUNCH
  317	}
