    29	bool compare_history(const std::vector<int32_t>& got,
    30	                     const std::vector<int32_t>& want, int32_t history_len) {
    31	  std::vector<int32_t> a(got.begin(), got.begin() + history_len);
    32	  std::vector<int32_t> b(want.begin(), want.begin() + history_len);
    33	  std::sort(a.begin(), a.end());
    34	  std::sort(b.begin(), b.end());
    35	  return a == b;
    36	}
    37	
    38	bool compare_tail(const std::vector<int32_t>& got, const std::vector<int32_t>& want,
    39	                  int32_t history_len, int32_t out_cols) {
    40	  for (int32_t i = history_len; i < out_cols; ++i)
    41	    if (got[i] != want[i]) return false;
    42	  return true;
    43	}
    44	
    45	struct Case {
    46	  const char* name;
    47	  int32_t batch_size;
