    74	  int32_t *dlengths = nullptr, *dout = nullptr, *dpage = nullptr;
    75	  int32_t *dpage_row = nullptr, *doffsets = nullptr, *drow_starts = nullptr, *dseq = nullptr;
    76	  CK(hipMalloc(&dscore, c.score.size() * sizeof(float)), "alloc score");
    77	  CK(hipMalloc(&dlengths, c.lengths.size() * sizeof(int32_t)), "alloc lengths");
    78	  CK(hipMalloc(&dout, want.size() * sizeof(int32_t)), "alloc out");
    79	  if (!c.page_table.empty()) CK(hipMalloc(&dpage, c.page_table.size() * sizeof(int32_t)), "alloc page");
    80	  if (!c.page_table_row_index.empty()) CK(hipMalloc(&dpage_row, c.page_table_row_index.size() * sizeof(int32_t)), "alloc page row");
    81	  if (!c.topk_indices_offset.empty()) CK(hipMalloc(&doffsets, c.topk_indices_offset.size() * sizeof(int32_t)), "alloc offsets");
    82	  if (!c.row_starts.empty()) CK(hipMalloc(&drow_starts, c.row_starts.size() * sizeof(int32_t)), "alloc row starts");
    83	  if (!c.seq_lens.empty()) CK(hipMalloc(&dseq, c.seq_lens.size() * sizeof(int32_t)), "alloc seq");
    84	
    85	  CK(hipMemcpy(dscore, c.score.data(), c.score.size() * sizeof(float), hipMemcpyHostToDevice), "cpy score");
    86	  CK(hipMemcpy(dlengths, c.lengths.data(), c.lengths.size() * sizeof(int32_t), hipMemcpyHostToDevice), "cpy lengths");
    87	  if (dpage) CK(hipMemcpy(dpage, c.page_table.data(), c.page_table.size() * sizeof(int32_t), hipMemcpyHostToDevice), "cpy page");
    88	  if (dpage_row) CK(hipMemcpy(dpage_row, c.page_table_row_index.data(), c.page_table_row_index.size() * sizeof(int32_t), hipMemcpyHostToDevice), "cpy page row");
    89	  if (doffsets) CK(hipMemcpy(doffsets, c.topk_indices_offset.data(), c.topk_indices_offset.size() * sizeof(int32_t), hipMemcpyHostToDevice), "cpy offsets");
    90	  if (drow_starts) CK(hipMemcpy(drow_starts, c.row_starts.data(), c.row_starts.size() * sizeof(int32_t), hipMemcpyHostToDevice), "cpy row starts");
    91	  if (dseq) CK(hipMemcpy(dseq, c.seq_lens.data(), c.seq_lens.size() * sizeof(int32_t), hipMemcpyHostToDevice), "cpy seq");
