   105	    const int32_t* gw = got.data() + static_cast<size_t>(row) * c.out_cols;
   106	    const int32_t* ww = want.data() + static_cast<size_t>(row) * c.out_cols;
   107	    ok &= compare_history(std::vector<int32_t>(gw, gw + c.out_cols),
   108	                          std::vector<int32_t>(ww, ww + c.out_cols), history_len);
   109	    ok &= compare_tail(std::vector<int32_t>(gw, gw + c.out_cols),
   110	                       std::vector<int32_t>(ww, ww + c.out_cols),
   111	                       history_len, c.out_cols);
