   153	        for (int32_t i = 0; i < 130; ++i) v[2 + i] = static_cast<float>(i);
   154	        return v;
   155	      }(),
   156	      {130},
   157	      {},
   158	      0,
   159	      {},
   160	      {},
   161	      {2},
   162	      {},
   163	  });
   164	  cases.push_back(Case{
   165	      "page table remap",
   166	      1, 132, 2, 256, 257,
   167	      [] {
   168	        std::vector<float> v(132);
   169	        v[0] = 1000.0f; v[1] = 999.0f;
   170	        for (int32_t i = 0; i < 130; ++i) v[2 + i] = static_cast<float>(i);
   171	        return v;
   172	      }(),
   173	      {130},
   174	      [] {
   175	        std::vector<int32_t> v(400);
   176	        for (int32_t i = 0; i < 400; ++i) v[i] = 200 + i;
   177	        return v;
   178	      }(),
   179	      400,
   180	      {0},
   181	      {},
   182	      {2},
   183	      {261},
   184	  });
   185	
   186	  int fails = 0;
