namespace {

bool compare_history(const std::vector<int32_t>& got,
                     const std::vector<int32_t>& want, int32_t history_len) {
  std::vector<int32_t> a(got.begin(), got.begin() + history_len);
  std::vector<int32_t> b(want.begin(), want.begin() + history_len);
  std::sort(a.begin(), a.end());
  std::sort(b.begin(), b.end());
  return a == b;
}

bool compare_tail(const std::vector<int32_t>& got, const std::vector<int32_t>& want,
                  int32_t history_len, int32_t out_cols) {
  for (int32_t i = history_len; i < out_cols; ++i)
    if (got[i] != want[i]) return false;
  return true;
}

struct Case {
  const char* name;
  int32_t batch_size;
  int32_t score_stride;
  int32_t pool_size;
  int32_t token_topk;
  int32_t out_cols;
  std::vector<float> score;
  std::vector<int32_t> lengths;
  std::vector<int32_t> page_table;
  int64_t page_table_stride;
  std::vector<int32_t> page_table_row_index;
  std::vector<int32_t> topk_indices_offset;
  std::vector<int32_t> row_starts;
  std::vector<int32_t> seq_lens;
};

bool run_case(const Case& c) {
  std::vector<int32_t> want(static_cast<size_t>(c.batch_size) * c.out_cols, -1);
  vkernels::kernels::dsa_topk_transform_cpu(
      c.batch_size, c.score.data(), c.lengths.data(), want.data(),
      c.score_stride, c.pool_size, c.token_topk, c.out_cols,
      c.page_table.empty() ? nullptr : c.page_table.data(), c.page_table_stride,
      c.page_table_row_index.empty() ? nullptr : c.page_table_row_index.data(),
      c.topk_indices_offset.empty() ? nullptr : c.topk_indices_offset.data(),
      c.row_starts.empty() ? nullptr : c.row_starts.data(),
      c.seq_lens.empty() ? nullptr : c.seq_lens.data());

  float* dscore = nullptr;
  int32_t *dlengths = nullptr, *dout = nullptr, *dpage = nullptr;
  int32_t *dpage_row = nullptr, *doffsets = nullptr, *drow_starts = nullptr, *dseq = nullptr;
  CK(hipMalloc(&dscore, c.score.size() * sizeof(float)), "alloc score");
  CK(hipMalloc(&dlengths, c.lengths.size() * sizeof(int32_t)), "alloc lengths");
  CK(hipMalloc(&dout, want.size() * sizeof(int32_t)), "alloc out");
  if (!c.page_table.empty()) CK(hipMalloc(&dpage, c.page_table.size() * sizeof(int32_t)), "alloc page");
  if (!c.page_table_row_index.empty()) CK(hipMalloc(&dpage_row, c.page_table_row_index.size() * sizeof(int32_t)), "alloc page row");
  if (!c.topk_indices_offset.empty()) CK(hipMalloc(&doffsets, c.topk_indices_offset.size() * sizeof(int32_t)), "alloc offsets");
  if (!c.row_starts.empty()) CK(hipMalloc(&drow_starts, c.row_starts.size() * sizeof(int32_t)), "alloc row starts");
  if (!c.seq_lens.empty()) CK(hipMalloc(&dseq, c.seq_lens.size() * sizeof(int32_t)), "alloc seq");

  CK(hipMemcpy(dscore, c.score.data(), c.score.size() * sizeof(float), hipMemcpyHostToDevice), "cpy score");
  CK(hipMemcpy(dlengths, c.lengths.data(), c.lengths.size() * sizeof(int32_t), hipMemcpyHostToDevice), "cpy lengths");
  if (dpage) CK(hipMemcpy(dpage, c.page_table.data(), c.page_table.size() * sizeof(int32_t), hipMemcpyHostToDevice), "cpy page");
  if (dpage_row) CK(hipMemcpy(dpage_row, c.page_table_row_index.data(), c.page_table_row_index.size() * sizeof(int32_t), hipMemcpyHostToDevice), "cpy page row");
  if (doffsets) CK(hipMemcpy(doffsets, c.topk_indices_offset.data(), c.topk_indices_offset.size() * sizeof(int32_t), hipMemcpyHostToDevice), "cpy offsets");
  if (drow_starts) CK(hipMemcpy(drow_starts, c.row_starts.data(), c.row_starts.size() * sizeof(int32_t), hipMemcpyHostToDevice), "cpy row starts");
  if (dseq) CK(hipMemcpy(dseq, c.seq_lens.data(), c.seq_lens.size() * sizeof(int32_t), hipMemcpyHostToDevice), "cpy seq");

  vkernels::kernels::hip::dsa_topk_transform(
      c.batch_size, dscore, dlengths, dout, c.score_stride, c.pool_size,
      c.token_topk, c.out_cols, dpage, c.page_table_stride, dpage_row,
      doffsets, drow_starts, dseq);
  CK(hipDeviceSynchronize(), "sync");

  std::vector<int32_t> got(want.size(), -1);
  CK(hipMemcpy(got.data(), dout, got.size() * sizeof(int32_t), hipMemcpyDeviceToHost), "rd out");

  bool ok = true;
  for (int32_t row = 0; row < c.batch_size; ++row) {
    const int32_t history_len = std::min(c.lengths[row], c.token_topk / c.pool_size) * c.pool_size;
    const int32_t* gw = got.data() + static_cast<size_t>(row) * c.out_cols;
    const int32_t* ww = want.data() + static_cast<size_t>(row) * c.out_cols;
    ok &= compare_history(std::vector<int32_t>(gw, gw + c.out_cols),
                          std::vector<int32_t>(ww, ww + c.out_cols), history_len);
    ok &= compare_tail(std::vector<int32_t>(gw, gw + c.out_cols),
                       std::vector<int32_t>(ww, ww + c.out_cols),
                       history_len, c.out_cols);
  }

  hipFree(dscore); hipFree(dlengths); hipFree(dout);
  if (dpage) hipFree(dpage);
  if (dpage_row) hipFree(dpage_row);
  if (doffsets) hipFree(doffsets);
  if (drow_starts) hipFree(drow_starts);
  if (dseq) hipFree(dseq);
  return ok;
}

